// Painted (outer) width of a box = what you see on screen, margin excluded
function paintedWidth(model, width, padding, border) {
  // content-box: width is only the content, so padding and border are added
  if (model === 'content-box') return width + 2 * padding + 2 * border;
  // border-box: width already includes padding and border
  return width;
}
function contentWidth(model, width, padding, border) {
  if (model === 'content-box') return width;
  return width - 2 * padding - 2 * border; // content shrinks instead
}
