// Specificity is a triple (ids, classes/attrs/pseudo-classes, types/pseudo-elements)
function spec(sel) {
  sel = sel.replace(/:where\([^)]*\)/g, '');            // :where() counts zero
  let a = 0, b = 0, c = 0;
  sel = sel.replace(/::[\w-]+/g, () => { c++; return ' '; }); // pseudo-elements
  sel = sel.replace(/#[\w-]+/g, () => { a++; return ' '; });  // ids
  sel = sel.replace(/\.[\w-]+|\[[^\]]*\]|:[\w-]+/g, () => { b++; return ' '; });
  for (const t of sel.split(/[\s>+~]+/)) if (t && t !== '*') c++; // type selectors
  return [a, b, c];
}
