// Each declaration gets a sort key; the highest key wins (compared left to right)
function key(d) {
  const imp = d.important ? 1 : 0;
  // normal: unlayered beats layered, later layer wins; important: reversed
  let layer;
  if (!d.important) layer = d.layer === null ? 1000 : d.layer;
  else layer = d.layer === null ? -1 : 100 - d.layer;
  return [imp, d.inline ? 1 : 0, layer, ...d.spec, d.order];
}
