// computed value of one property on an element whose parent has computed value 'parentVal'
function computed(prop, declared, parentVal) {
  if (declared === undefined) return inherited[prop] ? parentVal : initialValue[prop];
  if (declared === 'inherit') return parentVal;               // always the parent's value
  if (declared === 'initial') return initialValue[prop];      // spec default
  if (declared === 'unset') return inherited[prop] ? parentVal : initialValue[prop];
  if (declared === 'revert') return uaDefault[prop];          // browser default
  return declared;
}
