// Two touching vertical margins merge into one, unlike flex/grid gap
function collapse(a, b) {
  if (a >= 0 && b >= 0) return Math.max(a, b);   // both positive: the larger
  if (a <= 0 && b <= 0) return Math.min(a, b);   // both negative: the most negative
  return a + b;                                  // mixed: they add up
}
