// Relative luminance of an sRGB colour, as defined by WCAG
function lum(hex) {
  const n = parseInt(hex.slice(1), 16);
  const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map(v => {
    v /= 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * ch[0] + 0.7152 * ch[1] + 0.0722 * ch[2];
}
// ratio = (lighter + 0.05) / (darker + 0.05)
function ratio(fg, bg) {
  const a = lum(fg), b = lum(bg);
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}
const tests = [['#000000', '#ffffff'], ['#767676', '#ffffff'], ['#999999', '#ffffff'], ['#0000ff', '#ffffff']];
for (const [fg, bg] of tests) {
  const r = ratio(fg, bg);
  console.log(fg + ' on ' + bg + ' = ' + r.toFixed(2) + ':1  normal text AA ' +
    (r >= 4.5 ? 'pass' : 'FAIL') + ', large text AA ' + (r >= 3 ? 'pass' : 'FAIL'));
}

const container = 600; // px
function row(label, pct, padding, boxSizing) {
  // content-box adds padding on both sides to each column
  const col = boxSizing === 'border-box' ? container * pct / 100
                                          : container * pct / 100 + 2 * padding;
  const total = Math.round(col * 3 * 100) / 100;
  console.log(label.padEnd(34) + 'column=' + col.toFixed(2) + 'px total=' + total +
    'px -> ' + (total <= container ? 'fits on one line' : 'WRAPS (over by ' +
    Math.round((total - container) * 100) / 100 + 'px)'));
}
